#!/bin/bash
# build_gnutls.sh — GnuTLS self-contained cross-compile for aarch64-linux-ohos
# All hard dependencies live inside third_party/gnutls/ subtree:
#   - devel/nettle/        (cryptographic core, ships mini-gmp.c/h)
#   - lib/minitasn1/      (ASN.1, included via --with-included-libtasn1)
#   - lib/unistring/      (unicode, included via --with-included-unistring, generated by ./bootstrap from gnulib/)
# No external third_party/{gmp,libtasn1,libunistring,nettle} needed.
# Output -> ${ROOT_DIR}/build/gnutls_staging (for Wine bcrypt/schannel)
# Idempotent: skips if all products present.
set -euo pipefail

# Use build.sh env vars; fallback if sourced standalone
ROOT_DIR="${ROOT_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")/../.." && pwd)}"
OHOS_SDK="${OHOS_SDK:-${ROOT_DIR}/ohos_sdk/command-line-tools/sdk/default/openharmony}"
OHOS_TOOLCHAIN="${OHOS_TOOLCHAIN:-${OHOS_SDK}/native/llvm}"
BUILD_DIR="${BUILD_DIR:-${ROOT_DIR}/build}"

CLANG="${OHOS_TOOLCHAIN}/bin/clang"
SYSROOT="${OHOS_SDK}/native/sysroot"
TARGET=aarch64-linux-ohos
STAGING="${BUILD_DIR}/gnutls_staging"
GNUTLS_SRC="${ROOT_DIR}/third_party/gnutls"
NETTLE_SRC="${GNUTLS_SRC}/devel/nettle"
JOBS="${JOBS:-$(nproc)}"

GNUTLS_STAGING="${STAGING}"  # exported name for build.sh consumer
export GNUTLS_STAGING

# Final products (3 .so; gmp/libtasn1/libunistring are statically absorbed)
idempotent_done() {
    [ -f "$STAGING/lib/libgnutls.so.30" ] \
        && [ -f "$STAGING/lib/libnettle.so.8" ] \
        && [ -f "$STAGING/lib/libhogweed.so.6" ] \
        && [ -f "$STAGING/include/gnutls/gnutls.h" ] \
        && [ -f "$STAGING/lib/pkgconfig/gnutls.pc" ]
}

if idempotent_done; then
    echo "GnuTLS chain already built, skipping"
    exit 0
fi

mkdir -p "$STAGING/include" "$STAGING/lib" "$STAGING/lib/pkgconfig"

CROSS_CFLAGS="-O2 -fPIC -D__MUSL__"
CROSS_LDFLAGS="-fuse-ld=lld --sysroot=$SYSROOT --target=$TARGET"
export PKG_CONFIG_PATH="$STAGING/lib/pkgconfig"
export CC="$CLANG --target=$TARGET --sysroot=$SYSROOT"
export MAKEINFO=true  # skip texinfo docs

#--------------------------------------------------------------------------------
# Stage 1: nettle (with bundled mini-gmp; no system gmp required)
#--------------------------------------------------------------------------------
build_nettle() {
    local build="$BUILD_DIR/nettle_build_aarch64"
    echo "=== build nettle (mini-gmp) ==="
    rm -rf "$build"
    mkdir -p "$build"

    # devel/nettle ships only configure.ac; regenerate via autoreconf (host tool).
    # Scope AUTOMAKE flags to this autoreconf only: a global export leaks into
    # gnutls ./bootstrap, which treats $AUTOMAKE as the automake *binary path*
    # (not flags) and fails its prereq version check with "--foreign: not found".
    if [ ! -f "$NETTLE_SRC/configure" ]; then
        echo "--- autoreconf nettle ---"
        (cd "$NETTLE_SRC" && AUTOMAKE="--foreign --add-missing --copy" autoreconf -fi)
    fi

    (cd "$build" && \
        CC="$CC" CFLAGS="$CROSS_CFLAGS" LDFLAGS="$CROSS_LDFLAGS" \
        "$NETTLE_SRC/configure" \
            --host=aarch64-linux-gnu \
            --prefix="$STAGING" \
            --libdir="$STAGING/lib" \
            --enable-shared --disable-static \
            --enable-mini-gmp \
            --disable-documentation \
            --disable-assembler \
            --disable-openssl \
            --disable-dependency-tracking)

    make -C "$build" -j"$JOBS"
    make -C "$build" install
    # nettle.pc/hogweed.pc picked up via PKG_CONFIG_PATH below
}

#--------------------------------------------------------------------------------
# Stage 2: gnutls bootstrap (only if lib/unistring/ sources are missing)
#--------------------------------------------------------------------------------
bootstrap_gnutls() {
    # lib/unistring/*.c are generated by gnulib-tool in SUBDIRS (uninorm/,
    # unictype/, unistr/), not at the top level — count recursively, else the
    # check always reads 0 and re-runs bootstrap needlessly.
    local unistring_c
    unistring_c=$( { find "$GNUTLS_SRC/lib/unistring" -name '*.c' 2>/dev/null || true; } | wc -l)
    if [ "$unistring_c" -gt 0 ] && [ -f "$GNUTLS_SRC/configure" ] \
       && [ -d "$GNUTLS_SRC/gl" ] && [ -d "$GNUTLS_SRC/lib/unistring/m4" ]; then
        echo "--- gnutls bootstrap already done ---"
        return
    fi
    echo "--- gnutls bootstrap (gnulib-tool generates lib/unistring, gl/) ---"
    # ./bootstrap enforces a strict buildreq check that requires gtkdocize.
    # The post-import hook (bootstrap.conf) falls back gracefully when it is
    # absent, but the upfront check dies first. Stub gtkdocize (exit 0) so the
    # prereq check passes; the hook's `gtkdocize || {fallback}` then
    # "succeeds", leaving the existing gtk-doc.make in place (docs are disabled
    # via configure flags anyway).
    # SUBMODULE_NOFETCH=1 -> --no-fetch: uninitialized optional submodules
    # (devel/openssl, tests/suite/...) fail fast instead of hanging on network.
    # bootstrap has no `set -e`, so those non-fatal failures don't abort.
    # The stub must do the two things the real gtkdocize would, not just exit 0:
    #   1. create gtk-doc.make  (doc/reference/Makefile.am does `include` it ->
    #      "automake: cannot open < gtk-doc.make" on a fresh tree otherwise)
    #   2. install m4/gtk-doc.m4 (configure.ac calls GTK_DOC_CHECK
    #      unconditionally -> "possibly undefined macro" otherwise)
    # Mirrors the fallback stub in gnutls's bootstrap.conf; docs are disabled
    # via configure flags anyway.
    local stubbin="$BUILD_DIR/.stubbin"
    mkdir -p "$stubbin"
    cat > "$stubbin/gtkdocize" <<'STUB'
#!/bin/sh
cat > gtk-doc.make <<'EOF'
EXTRA_DIST =
CLEANFILES =
EOF
mkdir -p m4
cat > m4/gtk-doc.m4 <<'EOF'
dnl Minimal GTK_DOC_CHECK replacement: docs disabled for this build.
AC_DEFUN([GTK_DOC_CHECK],[
  AM_CONDITIONAL([ENABLE_GTK_DOC], [false])
  AM_CONDITIONAL([GTK_DOC_BUILD_HTML], [false])
  AM_CONDITIONAL([GTK_DOC_BUILD_PDF], [false])
])
EOF
exit 0
STUB
    chmod +x "$stubbin/gtkdocize"
    (cd "$GNUTLS_SRC" && \
        PATH="$stubbin:$PATH" \
        SUBMODULE_NOFETCH=1 \
        GNULIB_SRCDIR="$GNUTLS_SRC/gnulib" \
        ./bootstrap --skip-po --no-git --gnulib-srcdir="$GNUTLS_SRC/gnulib")
}

#--------------------------------------------------------------------------------
# Stage 3: gnutls (uses included libtasn1 + libunistring; links nettle/hogweed)
#--------------------------------------------------------------------------------
build_gnutls() {
    local build="$BUILD_DIR/gnutls_build_aarch64"
    echo "=== build gnutls (included libtasn1/unistring, mini-nettle) ==="
    rm -rf "$build"
    mkdir -p "$build"

    (cd "$build" && \
        CC="$CC" \
        CFLAGS="-I$STAGING/include $CROSS_CFLAGS" \
        LDFLAGS="-L$STAGING/lib $CROSS_LDFLAGS" \
        NETTLE_CFLAGS="-I$STAGING/include" \
        NETTLE_LIBS="-L$STAGING/lib -lnettle" \
        HOGWEED_CFLAGS="-I$STAGING/include" \
        HOGWEED_LIBS="-L$STAGING/lib -lhogweed" \
        "$GNUTLS_SRC/configure" \
            --host=aarch64-linux-gnu \
            --prefix="$STAGING" \
            --libdir="$STAGING/lib" \
            --with-nettle-mini \
            --with-included-libtasn1 \
            --with-included-unistring \
            --without-p11-kit \
            --without-tpm \
            --without-tpm2 \
            --without-libidn2 \
            --without-libxml2 \
            --without-brotli \
            --without-zstd \
            --without-libpsl \
            --without-idn \
            --without-unbound \
            --disable-nls \
            --disable-doc \
            --disable-tools \
            --disable-tests \
            --disable-full-test-suite \
            --disable-gtk-doc \
            --disable-gtk-doc-tools \
            --disable-cxx \
            --disable-guile \
            --disable-openssl-compatibility \
            --disable-valgrind-tests \
            --disable-code-coverage \
            --disable-libdane \
            --disable-dependency-tracking)

    # src/gl/tests triggers glibc-only macros under musl; drop the tests subdir
    # post-configure, pre-make (source untouched).
    if [ -f "$build/src/gl/Makefile" ]; then
        sed -i 's/^SUBDIRS = . tests/SUBDIRS = ./' "$build/src/gl/Makefile"
        touch "$build/src/gl/Makefile"
    fi

    make -C "$build" -j"$JOBS"
    make -C "$build" install

    # gnutls.pc should declare Requires: nettle, hogweed (not libtasn1/unistring,
    # which are statically absorbed). Ensure .pc nettle/hogweed paths resolve.
    if [ -f "$STAGING/lib/pkgconfig/gnutls.pc" ]; then
        sed -i "s|^prefix=.*|prefix=$STAGING|" "$STAGING/lib/pkgconfig/gnutls.pc"
    fi
}

build_nettle
bootstrap_gnutls
build_gnutls

echo "=== GnuTLS chain ready: $STAGING ==="
echo "Products (gmp/libtasn1/libunistring are statically absorbed into nettle/hogweed/gnutls):"
ls -1 "$STAGING/lib"/libgnutls.so.30* "$STAGING/lib"/libnettle.so.8* "$STAGING/lib"/libhogweed.so.6* 2>/dev/null
